@@ -0,0 +1,166 @@
+package com.example;
+
+import com.vaadin.flow.component.Key;
+import com.vaadin.flow.component.button.Button;
+import com.vaadin.flow.component.dialog.Dialog;
+import com.vaadin.flow.component.grid.Grid;
+import com.vaadin.flow.component.html.H1;
+import com.vaadin.flow.component.html.Paragraph;
+import com.vaadin.flow.component.orderedlayout.VerticalLayout;
+import com.vaadin.flow.component.notification.Notification;
+import com.vaadin.flow.component.textfield.EmailField;
+import com.vaadin.flow.component.textfield.TextArea;
+import com.vaadin.flow.component.textfield.TextField;
+import com.vaadin.flow.data.value.ValueChangeMode;
+import com.vaadin.flow.router.BeforeLeaveEvent;
+import com.vaadin.flow.router.BeforeLeaveObserver;
+import com.vaadin.flow.router.Route;
+import com.vaadin.flow.router.RouterLink;
+
+/** The application's contact form and the messages already submitted. */
+@Route("contact")
+public class ContactView extends VerticalLayout implements BeforeLeaveObserver {
+    private final TextField name = new TextField("Name");
+    private final EmailField email = new EmailField("Email");
+    private final TextField phone = new TextField("Phone");
+    private final TextArea message = new TextArea("Message");
+    private final Button send = new Button("Send");
+    private final Grid<ContactMessage> sentMessages = new Grid<>(ContactMessage.class, false);
+    private final MessageStore messageStore;
+
+    public ContactView(MessageStore messageStore) {
+        this.messageStore = messageStore;
+
+        sentMessages.addColumn(ContactMessage::name).setHeader("Name");
+        sentMessages.addColumn(ContactMessage::message).setHeader("Message");
+
+        name.setValueChangeMode(ValueChangeMode.EAGER);
+        email.setValueChangeMode(ValueChangeMode.EAGER);
+        phone.setValueChangeMode(ValueChangeMode.EAGER);
+        message.setValueChangeMode(ValueChangeMode.EAGER);
+        name.addValueChangeListener(event -> enableSendAfterEdit());
+        email.addValueChangeListener(event -> enableSendAfterEdit());
+        phone.addValueChangeListener(event -> enableSendAfterEdit());
+        message.addValueChangeListener(event -> enableSendAfterEdit());
+
+        send.addClickListener(event -> sendMessage());
+        send.addClickShortcut(Key.ENTER);
+
+        add(new H1("Contact"), new RouterLink("About", AboutView.class),
+                name, email, phone, message, send, sentMessages);
+        refreshMessages();
+    }
+
+    private void enableSendAfterEdit() {
+        send.setEnabled(true);
+    }
+
+    private void sendMessage() {
+        clearValidation();
+        if (!isValid()) {
+            return;
+        }
+
+        messageStore.add(new ContactMessage(name.getValue(), email.getValue(),
+                phone.getValue(), message.getValue()));
+        refreshMessages();
+        clearFields();
+        send.setEnabled(false);
+        Notification.show("Message sent");
+    }
+
+    private boolean isValid() {
+        boolean valid = true;
+        if (name.getValue().trim().isEmpty()) {
+            invalidate(name, "Name is required");
+            valid = false;
+        }
+
+        String emailAddress = email.getValue().trim();
+        String phoneNumber = phone.getValue().trim();
+        if (!emailAddress.isEmpty() && !isEmailAddress(emailAddress)) {
+            invalidate(email, "Enter a valid e-mail address");
+            valid = false;
+        } else if (emailAddress.isEmpty() && phoneNumber.isEmpty()) {
+            invalidate(email, "Give an e-mail address or a phone number");
+            valid = false;
+        }
+
+        if (message.getValue().trim().isEmpty()) {
+            invalidate(message, "Message is required");
+            valid = false;
+        } else if (message.getValue().length() > 500) {
+            invalidate(message, "Message must be at most 500 characters");
+            valid = false;
+        }
+        return valid;
+    }
+
+    private boolean isEmailAddress(String value) {
+        // This deliberately follows the practical single-address form used by
+        // HTML email inputs, rather than accepting a comma-separated list.
+        return value.matches("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$");
+    }
+
+    private void invalidate(TextField field, String error) {
+        field.setErrorMessage(error);
+        field.setInvalid(true);
+    }
+
+    private void invalidate(EmailField field, String error) {
+        field.setErrorMessage(error);
+        field.setInvalid(true);
+    }
+
+    private void invalidate(TextArea field, String error) {
+        field.setErrorMessage(error);
+        field.setInvalid(true);
+    }
+
+    private void clearValidation() {
+        name.setInvalid(false);
+        email.setInvalid(false);
+        phone.setInvalid(false);
+        message.setInvalid(false);
+    }
+
+    private void clearFields() {
+        name.clear();
+        email.clear();
+        phone.clear();
+        message.clear();
+        clearValidation();
+    }
+
+    private void refreshMessages() {
+        sentMessages.setItems(messageStore.all());
+    }
+
+    private boolean hasUnsavedInput() {
+        return !name.isEmpty() || !email.isEmpty() || !phone.isEmpty() || !message.isEmpty();
+    }
+
+    @Override
+    public void beforeLeave(BeforeLeaveEvent event) {
+        if (!hasUnsavedInput()) {
+            return;
+        }
+
+        BeforeLeaveEvent.ContinueNavigationAction navigation = event.postpone();
+        Dialog dialog = new Dialog();
+        dialog.setCloseOnEsc(false);
+        dialog.setCloseOnOutsideClick(false);
+        dialog.add(new Paragraph("Discard your unsent message?"));
+
+        Button keepEditing = new Button("Keep editing", click -> {
+            dialog.close();
+            navigation.cancel();
+        });
+        Button discard = new Button("Discard", click -> {
+            dialog.close();
+            navigation.proceed();
+        });
+        dialog.add(keepEditing, discard);
+        dialog.open();
+    }
+}
