+package com.example;
+
+import java.util.ArrayList;
+import java.util.List;
+
+import org.springframework.stereotype.Service;
+
+/**
+ * Application-scoped storage deliberately kept in memory.  It lets a new
+ * ContactView instance show messages sent by earlier visits to the route.
+ */
+@Service
+public class MessageStore {
+    private final List<ContactMessage> messages = new ArrayList<>();
+
+    public synchronized void add(ContactMessage message) {
+        messages.addFirst(message);
+    }
+
+    public synchronized List<ContactMessage> all() {
+        return List.copyOf(messages);
+    }
+}
